    Alpine.data('statutoryCalendar',()=>({jurisdiction:P.currentPlant.state,regulation:'all',tpi:'all',status:'all',get items(){return scope(P.fleetStatutory);},get agencies(){return P.agencies;},get filtered(){return this.items.filter(i=>(this.jurisdiction==='all'||i.jurisdiction_state===this.jurisdiction)&&(this.regulation==='all'||q(i.regulation+' '+i.reference,this.regulation))&&(this.tpi==='all'||i.tpi_agency===this.tpi)&&(this.status==='all'||i.status===this.status));},get monthly(){const m={};this.filtered.forEach(i=>{const k=i.scheduled_date.slice(0,7);m[k]=(m[k]||0)+1;});return m;},get months(){return Array.from({length:6},(_,n)=>{const d=new Date(S.today()+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');});},get readiness(){return this.items.length?Math.round(100*this.items.filter(i=>i.status==='valid').length/this.items.length):0;}}));
