    Alpine.data('sparesInventory',()=>({q:'',status:'all',get parts(){return visibleSpares();},get filtered(){return this.parts.filter(p=>(q(p.part_number,this.q)||q(p.name,this.q)||q(p.manufacturer,this.q))&&(this.status==='all'||p.status===this.status));},get lowCount(){return this.parts.filter(p=>p.status!=='ok').length;}}));
    Alpine.data('notificationsCenter',()=>({tab:'feed',get events(){return P.notifications.filter(e=>!e.plant_id||e.plant_id===S.plant);},get types(){return P.eventTypes;},get prefs(){return P.preferences;},get unread(){return this.events.filter(e=>!e.read).length;},toggle(code,ch){if(S.server&&ch!=='inapp'){dialog('Delivery integration required','<p class=\"pari-note\">In-app reminders are available. Operational email, push and WhatsApp alerts need a delivery adapter. SMTP currently supports account invitations and password resets. This channel remains inactive.</p>');return;}S.commit('Notification preference changed',p=>{p.preferences[code]||={};p.preferences[code][ch]=!p.preferences[code][ch];});toast(S.server?'Preference saved to your account.':'Preference saved locally.');},markAllRead(){S.commit('Notifications marked read',p=>p.notifications.filter(e=>!e.plant_id||e.plant_id===S.plant).forEach(e=>e.read=true));toast('All notifications marked read.');},markRead(e){S.commit('Notification read',()=>e.read=true);}}));
