    Alpine.data('registerFlow',()=>({step:1,org:{name:'',industry:'Steel & metals',gstin:''},plant:{name:'',state:'Maharashtra'},admin:{name:'',email:'',phone:'',password:''},agreed:true,init(){this.$watch('step',v=>document.dispatchEvent(new CustomEvent('pari:register-step',{detail:v})));},next(){const id=this.step===1?'orgName':'plantName',el=document.getElementById(id);if(!el.value.trim()){el.setCustomValidity('This field is required.');el.reportValidity();return;}el.setCustomValidity('');this.step=Math.min(3,this.step+1);},back(){this.step=Math.max(1,this.step-1);},async create(){try{if(S.server){await window.PARI_LIVE.api('/api/auth/register',{organization:this.org.name,plant:this.plant.name,state:({'Maharashtra':'MH','Jharkhand':'JH','Karnataka':'KA','Tamil Nadu':'TN','Andhra Pradesh':'AP','Gujarat':'GJ','Odisha':'OD','Uttar Pradesh':'UP'})[this.plant.state],name:this.admin.name,email:this.admin.email,password:this.admin.password});location.href='../app/dashboard.html';return;}if(!this.admin.name.trim()||!/^\S+@\S+\.\S+$/.test(this.admin.email)||this.admin.password.length<12||!this.agreed)throw Error('Enter your name, a valid email, a password of at least 12 characters, and agree to the test terms.');if(P.users.some(u=>u.email.toLowerCase()===this.admin.email.toLowerCase()))throw Error('This email already exists in the test workspace.');const salt=S.uid('salt'),hash=await S.hash(this.admin.password,salt);let u;S.commit('Test organization registered',p=>{const org={id:S.uid('org'),name:this.org.name,industry:this.org.industry,gstin:this.org.gstin,plan:'Local test',region:'IN'};p.organizations.push(org);Object.assign(p.org,org);const id=S.uid('plt');const plant={id,organization_id:org.id,name:this.plant.name,code:'TEST',state:({'Maharashtra':'MH','Jharkhand':'JH','Karnataka':'KA','Tamil Nadu':'TN','Andhra Pradesh':'AP','Gujarat':'GJ','Odisha':'OD','Uttar Pradesh':'UP'})[this.plant.state],crane_count:0};p.plants.push(plant);Object.assign(p.currentPlant,plant);u={id:S.uid('usr'),organization_id:p.org.id,name:this.admin.name,email:this.admin.email.trim().toLowerCase(),role:'Organization Admin',scope:plant.name,status:'active',mfa:false,last_active:'just now',avatar_initials:this.admin.name.split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase()};p.users.push(u);p.accounts.push({user_id:u.id,email:u.email,salt,hash,organization:this.org.name});});S.sessionSet(u);location.href='../app/dashboard.html';}catch(e){toast(e.message);}}}));
